 "price.free.desc": {"ja": "まず現状を知る。導入時点の基準でAI向けの出力までを無料で。", "en": "First, see where you stand. AI-facing output, based on the criteria at the time you install — free.", "zh": "先了解现状。按接入时的标准，免费输出面向AI的内容。", "zh-TW": "先了解現狀。依導入當時的標準，免費輸出面向AI的內容。", "ko": "먼저 현황을 파악하세요. 도입 시점 기준의 AI용 출력까지 무료로.", "es": "Primero, conoce tu situación. Incluye gratis la salida para IA según los criterios vigentes al instalar.", "fr": "Faites d'abord le point. Jusqu'aux sorties pour l'IA, gratuitement, selon les critères en vigueur à l'installation.", "de": "Erst den Status kennen. KI-Ausgabe nach dem Stand bei der Einrichtung – kostenlos."},
 "price.free.1": {"ja": "AI可読スコア診断（無料でも毎回出ます）", "en": "AI readability score check (every time, even on Free)", "zh": "AI可读性评分诊断（免费版每次也会给出）", "zh-TW": "AI可讀性評分診斷（免費版每次也會顯示）", "ko": "AI 가독성 점수 진단(무료에서도 매번 제공)", "es": "Diagnóstico de legibilidad para IA (siempre incluido, también gratis)", "fr": "Diagnostic du score de lisibilité IA (à chaque fois, même en gratuit)", "de": "KI-Lesbarkeits-Score (auch kostenlos bei jeder Prüfung)"},
 "price.free.2": {"ja": "導入時点の基準でschema・llms.txt・AIクローラー許可を出力", "en": "Schema, llms.txt and AI crawler access, based on the criteria at install time", "zh": "按接入时的标准输出schema、llms.txt与AI爬虫许可", "zh-TW": "依導入當時的標準輸出schema、llms.txt與AI爬蟲許可", "ko": "도입 시점 기준으로 schema·llms.txt·AI 크롤러 허용 출력", "es": "Schema, llms.txt y permiso a crawlers de IA según los criterios vigentes al instalar", "fr": "Schema, llms.txt et autorisation des crawlers IA, selon les critères en vigueur à l'installation", "de": "Schema, llms.txt und KI-Crawler-Freigabe nach dem Stand bei der Einrichtung"},
 "price.free.3": {"ja": "店情報の自動抽出", "en": "Automatic business-info extraction", "zh": "店铺信息自动提取", "zh-TW": "店家資訊自動擷取", "ko": "매장 정보 자동 추출", "es": "Extracción automática de datos del negocio", "fr": "Extraction automatique des infos", "de": "Automatische Erfassung der Geschäftsdaten"},
 "price.free.4": {"ja": "基準が前進すると、その分だけスコアは下がります", "en": "As the criteria move forward, your score drops by that much", "zh": "标准每向前一步，评分就相应下降", "zh-TW": "標準向前推進時，評分會相應下降", "ko": "기준이 앞서 나가면 그만큼 점수는 내려갑니다", "es": "Cuando los criterios avanzan, el score baja en esa medida", "fr": "Quand les critères progressent, votre score baisse d'autant", "de": "Entwickeln sich die Kriterien weiter, sinkt der Score entsprechend"},
 "price.free.cta": {"ja": "無料ではじめる", "en": "Start free", "zh": "免费开始", "zh-TW": "免費開始", "ko": "무료로 시작", "es": "Empezar gratis", "fr": "Commencer gratuitement", "de": "Kostenlos starten"},
